function worldToPx(chart, x, y) {
  return {
    x: chart.scales.x.getPixelForValue(x),
    y: chart.scales.y.getPixelForValue(y)
  };
}

function clippedSegment(m, b) {
  var xmin = -7, xmax = 7, ymin = -5, ymax = 5;
  var pts = [];
  function add(x, y) {
    if (x >= xmin - 1e-9 && x <= xmax + 1e-9 && y >= ymin - 1e-9 && y <= ymax + 1e-9) {
      for (var i = 0; i < pts.length; i++) {
        if (Math.abs(pts[i].x - x) < 1e-7 && Math.abs(pts[i].y - y) < 1e-7) return;
      }
      pts.push({ x: x, y: y });
    }
  }
  add(xmin, m * xmin + b);
  add(xmax, m * xmax + b);
  if (Math.abs(m) > 1e-12) {
    add((ymin - b) / m, ymin);
    add((ymax - b) / m, ymax);
  }
  if (pts.length < 2 && b >= ymin && b <= ymax) {
    pts = [{ x: xmin, y: b }, { x: xmax, y: b }];
  }
  if (pts.length > 2) {
    var best = [pts[0], pts[1]], bestD = -1;
    for (var a = 0; a < pts.length; a++) {
      for (var c = a + 1; c < pts.length; c++) {
        var dx = pts[a].x - pts[c].x, dy = pts[a].y - pts[c].y;
        var d = dx * dx + dy * dy;
        if (d > bestD) {
          bestD = d;
          best = [pts[a], pts[c]];
        }
      }
    }
    pts = best;
  }
  return pts.length >= 2 ? pts : null;
}

function drawArrowHead(ctx, from, to, color, size) {
  var ang = Math.atan2(to.y - from.y, to.x - from.x);
  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(to.x, to.y);
  ctx.lineTo(to.x - size * Math.cos(ang - Math.PI / 7), to.y - size * Math.sin(ang - Math.PI / 7));
  ctx.lineTo(to.x - size * Math.cos(ang + Math.PI / 7), to.y - size * Math.sin(ang + Math.PI / 7));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawArrowLine(ctx, p1, p2, color, width, dash, alpha, headSize) {
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  if (dash) ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(p1.x, p1.y);
  ctx.lineTo(p2.x, p2.y);
  ctx.stroke();
  ctx.setLineDash([]);
  drawArrowHead(ctx, p1, p2, color, headSize);
  drawArrowHead(ctx, p2, p1, color, headSize);
  ctx.restore();
}

function drawHaloText(ctx, text, x, y, color, size, align, baseline, italic) {
  ctx.save();
  ctx.font = (italic ? 'italic ' : '') + '600 ' + size + 'px Arial, sans-serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = baseline || 'middle';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.lineWidth = Math.max(2, size * 0.28);
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawBoxText(ctx, text, x, y, color, size, align) {
  ctx.save();
  ctx.font = '600 ' + size + 'px Arial, sans-serif';
  ctx.textAlign = align || 'left';
  ctx.textBaseline = 'middle';
  var w = ctx.measureText(text).width;
  var pad = size * 0.35;
  var left = align === 'center' ? x - w / 2 - pad : (align === 'right' ? x - w - pad : x - pad);
  ctx.fillStyle = 'rgba(255,255,255,0.86)';
  ctx.fillRect(left, y - size * 0.68, w + 2 * pad, size * 1.36);
  ctx.strokeStyle = 'rgba(80,80,80,0.18)';
  ctx.lineWidth = 1;
  ctx.strokeRect(left, y - size * 0.68, w + 2 * pad, size * 1.36);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawGridAxes(ctx, chart, s) {
  var ca = chart.chartArea;
  var x0 = chart.scales.x.getPixelForValue(0);
  var y0 = chart.scales.y.getPixelForValue(0);
  var tick = clamp(s * 0.012, 3, 5);
  var font = clamp(s * 0.034, 10, 14);

  ctx.save();
  ctx.strokeStyle = '#cfcfcf';
  ctx.lineWidth = 1;
  for (var x = -7; x <= 7; x++) {
    var px = chart.scales.x.getPixelForValue(x);
    ctx.beginPath();
    ctx.moveTo(px, ca.top);
    ctx.lineTo(px, ca.bottom);
    ctx.stroke();
  }
  for (var y = -5; y <= 5; y++) {
    var py = chart.scales.y.getPixelForValue(y);
    ctx.beginPath();
    ctx.moveTo(ca.left, py);
    ctx.lineTo(ca.right, py);
    ctx.stroke();
  }
  ctx.strokeStyle = '#bdbdbd';
  ctx.strokeRect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);

  ctx.strokeStyle = '#111111';
  ctx.fillStyle = '#111111';
  ctx.lineWidth = clamp(s * 0.0045, 1.2, 2);
  ctx.beginPath();
  ctx.moveTo(ca.left - 17, y0);
  ctx.lineTo(ca.right + 17, y0);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0, ca.bottom + 17);
  ctx.lineTo(x0, ca.top - 17);
  ctx.stroke();
  drawArrowHead(ctx, { x: ca.right, y: y0 }, { x: ca.right + 17, y: y0 }, '#111111', clamp(s * 0.021, 6, 9));
  drawArrowHead(ctx, { x: ca.left, y: y0 }, { x: ca.left - 17, y: y0 }, '#111111', clamp(s * 0.021, 6, 9));
  drawArrowHead(ctx, { x: x0, y: ca.top }, { x: x0, y: ca.top - 17 }, '#111111', clamp(s * 0.021, 6, 9));
  drawArrowHead(ctx, { x: x0, y: ca.bottom }, { x: x0, y: ca.bottom + 17 }, '#111111', clamp(s * 0.021, 6, 9));

  ctx.lineWidth = 1;
  for (var tx = -7; tx <= 7; tx++) {
    var tpx = chart.scales.x.getPixelForValue(tx);
    ctx.beginPath();
    ctx.moveTo(tpx, y0 - tick);
    ctx.lineTo(tpx, y0 + tick);
    ctx.stroke();
    if (tx !== 0) drawHaloText(ctx, String(tx), tpx, y0 + font * 1.12, '#222222', font, 'center', 'middle', false);
  }
  for (var ty = -5; ty <= 5; ty++) {
    var tpy = chart.scales.y.getPixelForValue(ty);
    ctx.beginPath();
    ctx.moveTo(x0 - tick, tpy);
    ctx.lineTo(x0 + tick, tpy);
    ctx.stroke();
    if (ty !== 0) drawHaloText(ctx, String(ty), x0 - font * 0.86, tpy, '#222222', font, 'right', 'middle', false);
  }
  drawHaloText(ctx, '0', x0 - font * 0.55, y0 + font * 0.85, '#222222', font, 'center', 'middle', false);
  drawHaloText(ctx, 'x', ca.right + 24, y0 + font * 0.06, '#111111', font + 3, 'center', 'middle', true);
  drawHaloText(ctx, 'y', x0 + font * 0.22, ca.top - 28, '#111111', font + 3, 'center', 'middle', true);
  ctx.restore();
}

function drawSelectedTriangle(ctx, chart, line, s) {
  if (!line) return;
  var run = line.run;
  var rise = line.rise;
  var xA = line.id === 'III' ? 1 : 0;
  var yA = line.m * xA + line.b;
  if (line.id === 'I') {
    xA = 0;
    yA = 3;
  }
  var A = worldToPx(chart, xA, yA);
  var B = worldToPx(chart, xA + run, yA);
  var C = worldToPx(chart, xA + run, yA + rise);
  var w = clamp(s * 0.008, 2, 3.5);
  var fs = clamp(s * 0.031, 10, 13);

  ctx.save();
  ctx.fillStyle = 'rgba(255,210,55,0.18)';
  ctx.beginPath();
  ctx.moveTo(A.x, A.y);
  ctx.lineTo(B.x, B.y);
  ctx.lineTo(C.x, C.y);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#222222';
  ctx.lineWidth = w;
  ctx.setLineDash([5, 4]);
  ctx.beginPath();
  ctx.moveTo(A.x, A.y);
  ctx.lineTo(B.x, B.y);
  ctx.lineTo(C.x, C.y);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = '#222222';
  ctx.beginPath();
  var q = clamp(s * 0.018, 5, 8);
  var sx = run >= 0 ? -1 : 1;
  var sy = rise >= 0 ? 1 : -1;
  ctx.moveTo(B.x, B.y);
  ctx.lineTo(B.x + sx * q, B.y);
  ctx.lineTo(B.x + sx * q, B.y + sy * q);
  ctx.lineTo(B.x, B.y + sy * q);
  ctx.stroke();

  var midRun = { x: (A.x + B.x) / 2, y: A.y + fs * 0.95 };
  var midRise = { x: C.x + fs * 0.72, y: (B.y + C.y) / 2 };
  drawBoxText(ctx, 'run ' + Math.abs(run), midRun.x, midRun.y, '#222222', fs, 'center');
  drawBoxText(ctx, 'rise ' + rise, midRise.x, midRise.y, '#222222', fs, 'left');

  var annX = clamp(C.x + fs * 0.9, chart.chartArea.left + 5, chart.chartArea.right - fs * 7);
  var annY = clamp(C.y - fs * 0.7, chart.chartArea.top + fs, chart.chartArea.bottom - fs);
  drawBoxText(ctx, 'm = ' + rise + '/' + run, annX, annY, line.color, fs, 'left');

  var intercept = worldToPx(chart, 0, line.b);
  var bTextY = clamp(intercept.y - fs * 1.25, chart.chartArea.top + fs, chart.chartArea.bottom - fs);
  drawBoxText(ctx, 'b = ' + fmt(line.b), intercept.x + fs * 0.9, bTextY, line.color, fs, 'left');
  ctx.restore();
}

function distanceToSegment(px, py, ax, ay, bx, by) {
  var dx = bx - ax, dy = by - ay;
  var len2 = dx * dx + dy * dy;
  if (!len2) return Math.hypot(px - ax, py - ay);
  var t = ((px - ax) * dx + (py - ay) * dy) / len2;
  t = clamp(t, 0, 1);
  var x = ax + t * dx, y = ay + t * dy;
  return Math.hypot(px - x, py - y);
}

function findHitLine(chart, evt) {
  if (!chart || !chart.chartArea) return null;
  var mx = evt.x, my = evt.y;
  var best = null, bestD = 999;
  for (var i = 0; i < lineDefs.length; i++) {
    var seg = clippedSegment(lineDefs[i].m, lineDefs[i].b);
    if (!seg) continue;
    var p1 = worldToPx(chart, seg[0].x, seg[0].y);
    var p2 = worldToPx(chart, seg[1].x, seg[1].y);
    var d = distanceToSegment(mx, my, p1.x, p1.y, p2.x, p2.y);
    if (d < bestD) {
      bestD = d;
      best = lineDefs[i];
    }
  }
  return bestD <= 10 ? best : null;
}

var linearMatcherPlugin = {
  id: 'linearMatcherPlugin',
  afterDraw: function (chart) {
    var ctx = chart.ctx;
    var ca = chart.chartArea;
    if (!ca) return;
    var s = Math.min(ca.right - ca.left, ca.bottom - ca.top);
    var lineW = clamp(s * 0.007, 2, 3.2);
    var candW = clamp(s * 0.009, 2.4, 4);
    var head = clamp(s * 0.024, 7, 11);
    var labelSize = clamp(s * 0.043, 13, 18);

    drawGridAxes(ctx, chart, s);

    ctx.save();
    ctx.beginPath();
    ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);
    ctx.clip();

    for (var i = 0; i < lineDefs.length; i++) {
      var line = lineDefs[i];
      var seg = clippedSegment(line.m, line.b);
      if (!seg) continue;
      var p1 = worldToPx(chart, seg[0].x, seg[0].y);
      var p2 = worldToPx(chart, seg[1].x, seg[1].y);
      var alpha = figureState.selected && figureState.selected !== line.id ? 0.26 : 1;
      if (figureState.selected === line.id) {
        ctx.save();
        ctx.globalAlpha = 0.55;
        ctx.strokeStyle = '#ffd84d';
        ctx.lineWidth = lineW + 7;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();
        ctx.restore();
      }
      drawArrowLine(ctx, p1, p2, line.color, lineW, null, alpha, head);
    }

    var cand = clippedSegment(figureState.m, figureState.b);
    if (cand) {
      var cp1 = worldToPx(chart, cand[0].x, cand[0].y);
      var cp2 = worldToPx(chart, cand[1].x, cand[1].y);
      drawArrowLine(ctx, cp1, cp2, '#6f2dbd', candW, [9, 6], 0.92, head);
    }
    ctx.restore();

    var selectedLine = null;
    for (var j = 0; j < lineDefs.length; j++) {
      if (lineDefs[j].id === figureState.selected) selectedLine = lineDefs[j];
    }
    drawSelectedTriangle(ctx, chart, selectedLine, s);

    for (var k = 0; k < lineDefs.length; k++) {
      var ld = lineDefs[k];
      var lp = worldToPx(chart, ld.label.x, ld.label.y);
      drawHaloText(ctx, ld.id, lp.x, lp.y, ld.color, labelSize, ld.label.align || 'center', 'middle', false);
    }
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    layout: { padding: { left: 31, right: 34, top: 43, bottom: 23 } },
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false }
    },
    scales: {
      x: { type: 'linear', min: -7, max: 7, display: false },
      y: { type: 'linear', min: -5, max: 5, display: false }
    },
    events: ['mousemove', 'mouseout', 'click'],
    onHover: function (event) {
      if (event.type === 'mouseout') {
        hideTooltip();
        canvas.style.cursor = 'default';
        return;
      }
      var hit = findHitLine(chart, event);
      if (hit) {
        canvas.style.cursor = 'pointer';
        var slopeText = hit.rise + '/' + hit.run;
        showTooltip(hit.name + ': y = ' + fmt(hit.m) + 'x ' + (hit.b >= 0 ? '+ ' : '- ') + fmt(Math.abs(hit.b)) + ';  b = ' + fmt(hit.b) + ',  m = ' + slopeText, event.native);
      } else {
        canvas.style.cursor = 'default';
        hideTooltip();
      }
    },
    onClick: function (event) {
      var hit = findHitLine(chart, event);
      if (!hit) return;
      figureState.selected = hit.id;
      setSliderValue('slopeM', hit.m);
      setSliderValue('interceptB', hit.b);
      figureState.m = hit.m;
      figureState.b = hit.b;
      chart.draw();
      showPopup(
        hit.name + ': y = ' + fmt(hit.m) + 'x ' + (hit.b >= 0 ? '+ ' : '- ') + fmt(Math.abs(hit.b)),
        hit.name + ' crosses the y-axis at b = ' + fmt(hit.b) + '. Its slope is rise/run = ' + hit.rise + '/' + hit.run + ', so the signed steepness matches m = ' + fmt(hit.m) + '.'
      );
    }
  },
  plugins: [linearMatcherPlugin]
});
window.__markRendered();

canvas.addEventListener('mouseleave', function () {
  hideTooltip();
  canvas.style.cursor = 'default';
});

function setSliderValue(id, value) {
  var input = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (input) input.value = String(value);
  if (out) out.value = fmt(value);
}

function update_slopeM(v) {
  figureState.m = v;
  chart.draw();
}

function update_interceptB(v) {
  figureState.b = v;
  chart.draw();
}

window.update_slopeM = update_slopeM;
window.update_interceptB = update_interceptB;

function applyStep(n) {
  figureState.step = clamp(n, 0, demoSteps.length - 1);
  var st = demoSteps[figureState.step];
  if (st.state.slopeM != null) {
    setSliderValue('slopeM', st.state.slopeM);
    figureState.m = st.state.slopeM;
  }
  if (st.state.interceptB != null) {
    setSliderValue('interceptB', st.state.interceptB);
    figureState.b = st.state.interceptB;
  }
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = st.narration;
  if (lab) lab.textContent = (figureState.step + 1) + '/' + demoSteps.length + ' ' + st.title;
  chart.draw();
}

function prevStep() {
  applyStep(figureState.step - 1);
}

function nextStep() {
  applyStep(figureState.step + 1);
}

window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: A line's equation y = mx + b can be matched to its graph by reading b as the y-intercept and m as the signed rise-over-run that controls direction and steepness.
KEY INSIGHT (what students should walk away understanding): To match a linear equation to a graph, first find where the line crosses the y-axis for b, then use the line's signed rise-over-run for m.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A line's equation y = mx + b can be matched to its graph by reading b as the y-intercept and m as the signed rise-over-run that controls direction and steepness.",
  "figureType": "line_plot",
  "elements": [
    "rectangular coordinate grid with light gray unit gridlines",
    "x-axis labeled x with arrowheads and tick labels from -7 to 7",
    "y-axis labeled y with arrowheads and tick labels from -5 to 5",
    "origin label 0",
    "orange line I with arrowheads at both ends, steep positive slope, crossing the y-axis near 3",
    "Roman numeral label I in orange near the top of the orange line",
    "light blue line II with arrowheads at both ends, shallow positive slope, crossing the y-axis at 3 and the x-axis near -6",
    "Roman numeral label II in light blue near the upper right endpoint",
    "teal line III with arrowheads at both ends, steep positive slope, crossing the y-axis at -3 and the x-axis near 1.5",
    "Roman numeral label III in teal near the upper right portion of the line",
    "dark blue line IV with arrowheads at both ends, steep negative slope, crossing the y-axis at 3 and descending to the lower right",
    "Roman numeral label IV in dark blue near the lower right endpoint",
    "movable candidate line with arrowheads at both ends, drawn as a bold dashed black or purple overlay",
    "highlight ring or glow around a clicked labeled line",
    "rise-over-run triangle markers on the selected line",
    "small text annotation showing selected line's slope as rise/run",
    "small text annotation showing selected line's y-intercept"
  ],
  "interactions": [
    {
      "id": "slopeM",
      "type": "slider",
      "label": "Slope m",
      "range": [
        -4,
        4,
        0.1
      ],
      "default": 0.5,
      "teaches": "Changing m shows that positive slopes rise left to right, negative slopes fall left to right, and larger absolute values make the line visually steeper"
    },
    {
      "id": "interceptB",
      "type": "slider",
      "label": "y-intercept b",
      "range": [
        -5,
        5,
        0.1
      ],
      "default": 3,
