  if (pts.length > 2) {
    var best = [pts[0], pts[1]], bestD = -1;
    for (var a = 0; a < pts.length; a++) {
      for (var c = a + 1; c < pts.length; c++) {
        var dx = pts[a].x - pts[c].x, dy = pts[a].y - pts[c].y;
        var d = dx * dx + dy * dy;
        if (d > bestD) {
          bestD = d;
          best = [pts[a], pts[c]];
        }
      }
    }
    pts = best;
  }
  return pts.length >= 2 ? pts : null;
}

function drawArrowHead(ctx, from, to, color, size) {
  var ang = Math.atan2(to.y - from.y, to.x - from.x);
  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(to.x, to.y);
  ctx.lineTo(to.x - size * Math.cos(ang - Math.PI / 7), to.y - size * Math.sin(ang - Math.PI / 7));
  ctx.lineTo(to.x - size * Math.cos(ang + Math.PI / 7), to.y - size * Math.sin(ang + Math.PI / 7));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawArrowLine(ctx, p1, p2, color, width, dash, alpha, headSize) {
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  if (dash) ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(p1.x, p1.y);
  ctx.lineTo(p2.x, p2.y);
  ctx.stroke();
  ctx.setLineDash([]);
  drawArrowHead(ctx, p1, p2, color, headSize);
  drawArrowHead(ctx, p2, p1, color, headSize);
  ctx.restore();
}

function drawHaloText(ctx, text, x, y, color, size, align, baseline, italic, weight) {
  ctx.save();
  ctx.font = (italic ? 'italic ' : '') + (weight || '600') + ' ' + size + 'px Arial, sans-serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = baseline || 'middle';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.95)';
  ctx.lineWidth = Math.max(2, size * 0.26);
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawBoxText(ctx, text, x, y, color, size, align) {
  ctx.save();
  ctx.font = '600 ' + size + 'px Arial, sans-serif';
  ctx.textAlign = align || 'left';
  ctx.textBaseline = 'middle';
  var w = ctx.measureText(text).width;
  var pad = size * 0.33;
  var left = align === 'center' ? x - w / 2 - pad : (align === 'right' ? x - w - pad : x - pad);
  ctx.fillStyle = 'rgba(255,255,255,0.9)';
  ctx.fillRect(left, y - size * 0.7, w + 2 * pad, size * 1.4);
  ctx.strokeStyle = 'rgba(60,60,60,0.18)';
  ctx.lineWidth = 1;
  ctx.strokeRect(left, y - size * 0.7, w + 2 * pad, size * 1.4);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawGridAxes(ctx, chart, s) {
  var p = plotMap;
  var x0 = worldToPx(0, 0).x;
  var y0 = worldToPx(0, 0).y;
  var tick = clamp(s * 0.011, 3, 5);
  var font = clamp(s * 0.034, 9, 13);
  var axisW = clamp(s * 0.0045, 1.2, 2);

  ctx.save();
  ctx.strokeStyle = '#c9c9c9';
  ctx.lineWidth = 1;
  for (var x = -7; x <= 7; x++) {
    var px = worldToPx(x, 0).x;
    ctx.beginPath();
    ctx.moveTo(px, p.top);
    ctx.lineTo(px, p.bottom);
    ctx.stroke();
  }
  for (var y = -5; y <= 5; y++) {
    var py = worldToPx(0, y).y;
    ctx.beginPath();
    ctx.moveTo(p.left, py);
    ctx.lineTo(p.right, py);
    ctx.stroke();
  }
  ctx.strokeStyle = '#bcbcbc';
  ctx.strokeRect(p.left, p.top, p.right - p.left, p.bottom - p.top);

  ctx.strokeStyle = '#111111';
  ctx.fillStyle = '#111111';
  ctx.lineWidth = axisW;
  ctx.beginPath();
  ctx.moveTo(p.left - p.axisExtra, y0);
  ctx.lineTo(p.right + p.axisExtra, y0);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0, p.bottom + p.axisExtra);
  ctx.lineTo(x0, p.top - p.axisExtra);
  ctx.stroke();

  var head = clamp(s * 0.022, 6, 9);
  drawArrowHead(ctx, { x: p.right, y: y0 }, { x: p.right + p.axisExtra, y: y0 }, '#111111', head);
  drawArrowHead(ctx, { x: p.left, y: y0 }, { x: p.left - p.axisExtra, y: y0 }, '#111111', head);
  drawArrowHead(ctx, { x: x0, y: p.top }, { x: x0, y: p.top - p.axisExtra }, '#111111', head);
  drawArrowHead(ctx, { x: x0, y: p.bottom }, { x: x0, y: p.bottom + p.axisExtra }, '#111111', head);

  ctx.lineWidth = 1;
  for (var tx = -7; tx <= 7; tx++) {
    var tpx = worldToPx(tx, 0).x;
    ctx.beginPath();
    ctx.moveTo(tpx, y0 - tick);
    ctx.lineTo(tpx, y0 + tick);
    ctx.stroke();
    if (tx !== 0 && p.unit > 20) drawHaloText(ctx, String(tx), tpx, y0 + font * 1.08, '#222222', font, 'center', 'middle', false, '500');
  }
  for (var ty = -5; ty <= 5; ty++) {
    var tpy = worldToPx(0, ty).y;
    ctx.beginPath();
    ctx.moveTo(x0 - tick, tpy);
    ctx.lineTo(x0 + tick, tpy);
    ctx.stroke();
    if (ty !== 0 && p.unit > 20) drawHaloText(ctx, String(ty), x0 - font * 0.72, tpy, '#222222', font, 'right', 'middle', false, '500');
  }
  drawHaloText(ctx, '0', x0 - font * 0.55, y0 + font * 0.84, '#222222', font, 'center', 'middle', false, '500');
  drawHaloText(ctx, 'x', p.right + p.axisExtra + font * 0.55, y0, '#111111', font + 3, 'center', 'middle', true, '600');
  drawHaloText(ctx, 'y', x0, p.top - p.axisExtra - font * 0.7, '#111111', font + 3, 'center', 'middle', true, '600');
  ctx.restore();
}

function drawSelectedTriangle(ctx, line, s) {
  if (!line) return;
  var xA = 0;
  if (line.id === 'II') xA = 0;
  if (line.id === 'III') xA = 1;
  if (line.id === 'IV') xA = 0;
  var yA = line.m * xA + line.b;
  var A = worldToPx(xA, yA);
  var B = worldToPx(xA + line.run, yA);
  var C = worldToPx(xA + line.run, yA + line.rise);
  var w = clamp(s * 0.008, 2, 3.5);
  var fs = clamp(s * 0.031, 10, 13);

  ctx.save();
  ctx.fillStyle = 'rgba(255,210,55,0.18)';
  ctx.beginPath();
  ctx.moveTo(A.x, A.y);
  ctx.lineTo(B.x, B.y);
  ctx.lineTo(C.x, C.y);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = '#222222';
  ctx.lineWidth = w;
  ctx.setLineDash([5, 4]);
  ctx.beginPath();
  ctx.moveTo(A.x, A.y);
  ctx.lineTo(B.x, B.y);
  ctx.lineTo(C.x, C.y);
  ctx.stroke();
  ctx.setLineDash([]);

  var q = clamp(s * 0.017, 5, 8);
  var sy = line.rise >= 0 ? -1 : 1;
  ctx.beginPath();
  ctx.moveTo(B.x, B.y);
  ctx.lineTo(B.x - q, B.y);
  ctx.lineTo(B.x - q, B.y + sy * q);
  ctx.lineTo(B.x, B.y + sy * q);
  ctx.stroke();

  drawBoxText(ctx, 'run ' + Math.abs(line.run), (A.x + B.x) / 2, A.y + fs * 0.95, '#222222', fs, 'center');
  drawBoxText(ctx, 'rise ' + line.rise, C.x + fs * 0.75, (B.y + C.y) / 2, '#222222', fs, 'left');

  var annX = clamp(C.x + fs * 0.9, plotMap.left + fs, plotMap.right - fs * 7);
  var annY = clamp(C.y - fs * 0.7, plotMap.top + fs, plotMap.bottom - fs);
  drawBoxText(ctx, 'm = ' + line.rise + '/' + line.run, annX, annY, line.color, fs, 'left');

  var intercept = worldToPx(0, line.b);
  var bTextY = clamp(intercept.y - fs * 1.25, plotMap.top + fs, plotMap.bottom - fs);
  drawBoxText(ctx, 'b = ' + fmt(line.b), intercept.x + fs * 0.9, bTextY, line.color, fs, 'left');
  ctx.restore();
}

function distanceToSegment(px, py, ax, ay, bx, by) {
  var dx = bx - ax, dy = by - ay;
  var len2 = dx * dx + dy * dy;
  if (!len2) return Math.hypot(px - ax, py - ay);
  var t = ((px - ax) * dx + (py - ay) * dy) / len2;
  t = clamp(t, 0, 1);
  var x = ax + t * dx, y = ay + t * dy;
  return Math.hypot(px - x, py - y);
}

function findHitLine(evt) {
  if (!plotMap || !evt) return null;
  var mx = evt.x, my = evt.y;
  var best = null, bestD = 999;
  for (var i = 0; i < lineDefs.length; i++) {
    var seg = clippedSegment(lineDefs[i].m, lineDefs[i].b);
    if (!seg) continue;
    var p1 = worldToPx(seg[0].x, seg[0].y);
    var p2 = worldToPx(seg[1].x, seg[1].y);
    var d = distanceToSegment(mx, my, p1.x, p1.y, p2.x, p2.y);
    if (d < bestD) {
      bestD = d;
      best = lineDefs[i];
    }
  }
  return bestD <= clamp(plotMap.unit * 0.18, 7, 11) ? best : null;
}

var linearMatcherPlugin = {
  id: 'linearMatcherPlugin',
  beforeDraw: function (chart) {
    var ctx = chart.ctx;
    ctx.save();
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, chart.width, chart.height);
    ctx.restore();
  },
  afterDraw: function (chart) {
    var ctx = chart.ctx;
    plotMap = computePlotMap(chart);
    var s = Math.min(plotMap.right - plotMap.left, plotMap.bottom - plotMap.top);
    var lineW = clamp(s * 0.007, 2, 3.2);
    var candW = clamp(s * 0.009, 2.3, 3.8);
    var head = clamp(s * 0.024, 7, 11);
    var labelSize = clamp(s * 0.043, 13, 18);

    drawGridAxes(ctx, chart, s);

    ctx.save();
    ctx.beginPath();
    ctx.rect(plotMap.left, plotMap.top, plotMap.right - plotMap.left, plotMap.bottom - plotMap.top);
    ctx.clip();

    for (var i = 0; i < lineDefs.length; i++) {
      var line = lineDefs[i];
      var seg = clippedSegment(line.m, line.b);
      if (!seg) continue;
      var p1 = worldToPx(seg[0].x, seg[0].y);
      var p2 = worldToPx(seg[1].x, seg[1].y);
      var alpha = figureState.selected && figureState.selected !== line.id ? 0.27 : 1;
      if (figureState.selected === line.id) {
        ctx.save();
        ctx.globalAlpha = 0.58;
        ctx.strokeStyle = '#ffd84d';
        ctx.lineWidth = lineW + 7;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();
        ctx.restore();
      }
      drawArrowLine(ctx, p1, p2, line.color, lineW, null, alpha, head);
    }

    if (figureState.candidateVisible) {
      var cand = clippedSegment(figureState.m, figureState.b);
      if (cand) {
        var cp1 = worldToPx(cand[0].x, cand[0].y);
        var cp2 = worldToPx(cand[1].x, cand[1].y);
        drawArrowLine(ctx, cp1, cp2, '#6f2dbd', candW, [8, 5], 0.9, head);
      }
    }
    ctx.restore();

    var selectedLine = null;
    for (var j = 0; j < lineDefs.length; j++) {
      if (lineDefs[j].id === figureState.selected) selectedLine = lineDefs[j];
    }
    drawSelectedTriangle(ctx, selectedLine, s);

    for (var k = 0; k < lineDefs.length; k++) {
      var ld = lineDefs[k];
      var lp = worldToPx(ld.label.x, ld.label.y);
      drawHaloText(ctx, ld.id, lp.x, lp.y, ld.color, labelSize, ld.label.align || 'center', 'middle', false, '600');
    }
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    layout: { padding: { left: 18, right: 18, top: 18, bottom: 18 } },
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false }
    },
    scales: {
      x: { type: 'linear', min: -7, max: 7, display: false },
      y: { type: 'linear', min: -5, max: 5, display: false }
    },
    events: ['mousemove', 'mouseout', 'click'],
    onHover: function (event) {
      if (event.type === 'mouseout') {
        hideTooltip();
        canvas.style.cursor = 'default';
        return;
      }
      var hit = findHitLine(event);
      if (hit) {
        canvas.style.cursor = 'pointer';
        var slopeText = hit.rise + '/' + hit.run;
        showTooltip(hit.name + ': y = ' + fmt(hit.m) + 'x ' + (hit.b >= 0 ? '+ ' : '- ') + fmt(Math.abs(hit.b)) + ';  b = ' + fmt(hit.b) + ',  m = ' + slopeText, event.native);
      } else {
        canvas.style.cursor = 'default';
        hideTooltip();
      }
    },
    onClick: function (event) {
      var hit = findHitLine(event);
      if (!hit) return;
      figureState.selected = hit.id;
      setSliderValue('slopeM', hit.m);
      setSliderValue('interceptB', hit.b);
      figureState.m = hit.m;
      figureState.b = hit.b;
      chart.draw();
      showPopup(
        hit.name + ': y = ' + fmt(hit.m) + 'x ' + (hit.b >= 0 ? '+ ' : '- ') + fmt(Math.abs(hit.b)),
        hit.name + ' crosses the y-axis at b = ' + fmt(hit.b) + '. Its slope is signed rise/run = ' + hit.rise + '/' + hit.run + ', which determines its direction and steepness.'
      );
    }
  },
  plugins: [linearMatcherPlugin]
});
window.__markRendered();

canvas.addEventListener('mouseleave', function () {
  hideTooltip();
  canvas.style.cursor = 'default';
});

function setSliderValue(id, value) {
  var input = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (input) input.value = String(value);
  if (out) out.value = fmt(value);
}

function update_slopeM(v) {
  figureState.m = v;
  figureState.candidateVisible = true;
  chart.draw();
}

function update_interceptB(v) {
  figureState.b = v;
  figureState.candidateVisible = true;
  chart.draw();
}

window.update_slopeM = update_slopeM;
window.update_interceptB = update_interceptB;

function applyStep(n) {
  figureState.step = clamp(n, 0, demoSteps.length - 1);
  var st = demoSteps[figureState.step];
  if (st.state.slopeM != null) {
    setSliderValue('slopeM', st.state.slopeM);
    figureState.m = st.state.slopeM;
  }
  if (st.state.interceptB != null) {
    setSliderValue('interceptB', st.state.interceptB);
    figureState.b = st.state.interceptB;
  }
  figureState.candidateVisible = !!st.state.candidateVisible;
  figureState.selected = st.state.selected || null;
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = st.narration;
  if (lab) lab.textContent = (figureState.step + 1) + '/' + demoSteps.length + ' ' + st.title;
  chart.draw();
}

function prevStep() {
  applyStep(figureState.step - 1);
}

function nextStep() {
  applyStep(figureState.step + 1);
}

window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
